# FUNÇÕES
# ============================================================
def converter_duracao(texto):
    texto = str(texto).strip().lower()
    if not texto: return None
    if ":" in texto:
        partes = texto.split(":")
        try:
            if len(partes) == 3:
                h,m,s = map(int,partes)
                if h < 0 or m < 0 or s < 0 or m >= 60 or s >= 60: return None
                return h*3600+m*60+s
            if len(partes) == 2:
                m,s = map(int,partes)
                if m < 0 or s < 0 or s >= 60: return None
                return m*60+s
        except ValueError: return None
    p = re.fullmatch(r"\s*(?:(\d+(?:[.,]\d+)?)\s*h)?\s*(?:(\d+(?:[.,]\d+)?)\s*min)?\s*(?:(\d+(?:[.,]\d+)?)\s*s)?\s*",texto)
    if p and any(p.groups()):
        try:
            h=float((p.group(1) or "0").replace(",",".")); m=float((p.group(2) or "0").replace(",",".")); s=float((p.group(3) or "0").replace(",","."))
            if h<0 or m<0 or s<0 or m>=60 or s>=60: return None
            return int(round(h*3600+m*60+s))
        except ValueError: return None
    try:
        m=float(texto.replace(",",".")); return int(round(m*60)) if m>=0 else None
    except ValueError: return None

def formatar_tempo(segundos):
    segundos=int(round(segundos)); h=segundos//3600; m=(segundos%3600)//60; s=segundos%60
    return f"{h:02d}:{m:02d}:{s:02d}"

def formatar_idade(idade_ma):
    if idade_ma >= 1000: return f"{idade_ma/1000:.3f} Ga"
    if idade_ma >= 1: return f"{idade_ma:.2f} Ma"
    if idade_ma >= 0.001: return f"{idade_ma*1000:.1f} ka"
    return f"{idade_ma*1_000_000:,.0f} anos".replace(",", ".")

def localizar_tempo_geologico(idade_ma):
    for intervalo in INTERVALOS:
        if intervalo["fim"] < idade_ma <= intervalo["inicio"]: return intervalo
    if idade_ma == 0: return INTERVALOS[-1]
    return None

def eventos_do_intervalo(intervalo):
    periodo=intervalo.get("período"); era=intervalo.get("era"); eon=intervalo.get("éon")
    if periodo and periodo != "—" and periodo in DESTAQUES: eventos=DESTAQUES[periodo]
    elif era in DESTAQUES: eventos=DESTAQUES[era]
    else: eventos=DESTAQUES.get(eon, [])
    return eventos[:2]

def extrair_json(texto):
    texto=texto.strip()
    if texto.startswith("```"):
        texto=re.sub(r"^```(?:json)?\s*","",texto); texto=re.sub(r"\s*```$","",texto)
    i=texto.find("{"); j=texto.rfind("}")
    if i==-1 or j==-1: return None
    try: return json.loads(texto[i:j+1])
    except json.JSONDecodeError: return None

def consultar_duracao_ia(nome_obra):
    """
    Pesquisa vários resultados na Wikidata e só aceita um resultado que tenha
    duração adequada. Dá prioridade a filmes/produções audiovisuais e tenta
    todos os candidatos antes de informar que a duração não foi encontrada.
    """
    api = "https://www.wikidata.org/w/api.php"
    headers = {
        "User-Agent": "PPCC-DGL7067-07110/1.0 (ferramenta didatica)"
    }

    def buscar(termo, idioma):
        params = {
            "action": "wbsearchentities",
            "search": termo,
            "language": idioma,
            "uselang": idioma,
            "format": "json",
            "limit": 10,
        }
        resposta = requests.get(api, params=params, headers=headers, timeout=10)
        resposta.raise_for_status()
        return resposta.json().get("search", [])

    def obter_entidade(qid):
        params = {
            "action": "wbgetentities",
            "ids": qid,
            "props": "claims|labels|descriptions",
            "languages": "pt|en",
            "format": "json",
        }
        resposta = requests.get(api, params=params, headers=headers, timeout=10)
        resposta.raise_for_status()
        return resposta.json().get("entities", {}).get(qid, {})

    def extrair_duracao(claims):
        resultados = []

        for claim in claims.get("P2047", []):
            valor = claim.get("mainsnak", {}).get("datavalue", {}).get("value", {})

            try:
                amount = float(str(valor.get("amount", "")).replace("+", ""))
            except (ValueError, TypeError):
                continue

            unit = str(valor.get("unit", ""))

            if "Q7727" in unit:       # minuto
                minutos = amount
            elif "Q25201" in unit:    # segundo
                minutos = amount / 60
            elif unit in ("1", "http://www.wikidata.org/entity/1"):
                minutos = amount
            else:
                continue

            if 1 <= minutos <= 1440:
                resultados.append(round(minutos))

        return resultados

    try:
        termo = nome_obra.strip()
        if not termo:
            return {"ok": False, "erro": "Digite o nome da obra."}

        # Pesquisa em português e inglês, removendo duplicatas.
        resultados = buscar(termo, "pt")
        resultados += buscar(termo, "en")

        unicos = {}
        for item in resultados:
            qid = item.get("id")
            if qid:
                unicos[qid] = item

        candidatos = list(unicos.values())

        # Pontua os candidatos para evitar escolher, por exemplo, um jogo
        # quando o usuário procura um filme.
        termo_norm = termo.casefold()

        def pontuacao(item):
            label = item.get("label", "").casefold()
            desc = item.get("description", "").casefold()

            pontos = 0

            if label == termo_norm:
                pontos += 100
            elif termo_norm in label:
                pontos += 40

            # Tipos audiovisuais recebem prioridade.
            if any(x in desc for x in [
                "film", "filme", "movie", "cinema",
                "television film", "television series",
                "série de televisão", "miniseries",
                "minissérie", "episode", "episódio"
            ]):
                pontos += 80

            # Outros tipos recebem penalização.
            if any(x in desc for x in [
                "video game", "videogame", "videojogo",
                "board game", "jogo de tabuleiro",
                "album", "song", "book", "livro",
                "comic", "comics", "banda desenhada"
            ]):
                pontos -= 100

            return pontos

        candidatos.sort(key=pontuacao, reverse=True)

        # Consulta vários candidatos. Não para no primeiro resultado sem duração.
        for item in candidatos[:10]:
            qid = item.get("id")
            if not qid:
                continue

            entidade = obter_entidade(qid)
            claims = entidade.get("claims", {})
            duracoes = extrair_duracao(claims)

            if not duracoes:
                continue

            labels = entidade.get("labels", {})
            descricoes = entidade.get("descriptions", {})

            titulo = (
                labels.get("pt", {}).get("value")
                or labels.get("en", {}).get("value")
                or item.get("label")
                or nome_obra
            )

            descricao = (
                descricoes.get("pt", {}).get("value")
                or descricoes.get("en", {}).get("value")
                or item.get("description", "")
            )

            return {
                "ok": True,
                "obra": titulo,
                "ano": "",
                "duracao_minutos": duracoes[0],
                "fonte": "Wikidata",
                "url": f"https://www.wikidata.org/wiki/{qid}",
                "descricao": descricao,
                "observacao": (
                    "A duração foi localizada na Wikidata. "
                    "A conversão para a escala de tempo geológico "
                    "é realizada exclusivamente pelo algoritmo do programa."
                )
            }

        return {
            "ok": False,
            "erro": (
                "A pesquisa encontrou resultados, mas nenhum dos candidatos "
                "consultados possui uma duração adequada cadastrada."
            )
        }

    except requests.Timeout:
        return {
            "ok": False,
            "erro": "A consulta demorou demais para responder. Tente novamente."
        }
    except requests.RequestException:
        return {
            "ok": False,
            "erro": "Não foi possível acessar a fonte de consulta no momento."
        }
    except Exception as exc:
        return {
            "ok": False,
            "erro": f"Erro na consulta automática: {exc}"
        }

def tempo_da_idade(idade_ma,duracao):
    return max(0,min(1,1-idade_ma/4540.0))*duracao

